Algoritmo Paraguas
  Definir llueve Como Logico <- Verdadero;
  Si llueve Entonces
    Escribir "Llevo el paraguas";
  FinSi
  Escribir "Salgo de casa";
FinAlgoritmo

Algoritmo Montana
  Definir estatura Como Entero <- 128;
  Si estatura >= 120 Entonces
    Escribir "Puedes subir a la montaña rusa";
  Sino
    Escribir "Todavía no: vuelve el año que viene";
  FinSi
FinAlgoritmo

Algoritmo Semaforo
  Definir nota Como Entero <- 7;
  Si nota >= 9 Entonces
    Escribir "Excelente";
  Sino
    Si nota >= 6 Entonces
      Escribir "Aprobado";
    Sino
      Escribir "A repasar";
    FinSi
  FinSi
FinAlgoritmo

Algoritmo Corto
  Definir divisor Como Entero <- 0;
  Si divisor <> 0 Y 10 / divisor > 1 Entonces
    Escribir "Grande";
  Sino
    Escribir "No se puede dividir";
  FinSi
FinAlgoritmo

Algoritmo ErrorNumero
  Definir edad Como Entero <- 12;
  Si edad Entonces
    Escribir "Hola";
  FinSi
FinAlgoritmo

Algoritmo ErrorEntonces
  Definir edad Como Entero <- 12;
  Si edad > 10
    Escribir "Hola";
  FinSi
FinAlgoritmo

Algoritmo ErrorCierre
  Definir edad Como Entero <- 12;
  Si edad > 10 Entonces
    Escribir "Hola";
FinAlgoritmo
